62	class Logger:
63	    def __init__(self, logdir, step):
64	        self._logdir = logdir
65	        self._writer = SummaryWriter(log_dir=str(logdir), max_queue=1000)
66	        self._last_step = None
67	        self._last_time = None
68	        self._scalars = {}
69	        self._images = {}
