515	            ) else 0
516	            gate_active = (
517	                gate is not None and step > config.gate_curriculum_phase1
518	            )
519	
520	            def step_fn(prev, _):
521	                state, _, _, prev_dt = prev
522	                feat = dynamics.get_feat(state)
523	                inp = feat.detach()
524	                action = policy(inp).sample()
