27	
28	def read_eval_returns(path):
29	    evals = {}
30	    try:
31	        with open(path) as f:
32	            for line in f:
33	                line = line.strip()
34	                if not line:
35	                    continue
36	                try:
37	                    rec = json.loads(line)
38	                except json.JSONDecodeError:
39	                    continue
40	                if "eval_return" in rec and "step" in rec:
