43	        pass
44	    return evals
45	
46	
47	def log_result(result):
48	    with open(RESULTS_FILE, "a") as f:
49	        f.write(json.dumps(result) + "\n")
50	
51	
52	def main():
53	    judged = set()
54	
55	    if os.path.exists(RESULTS_FILE):
56	        try:
57	            with open(RESULTS_FILE) as f:
58	                for line in f:
59	                    line = line.strip()
60	                    if not line:
61	                        continue
62	                    rec = json.loads(line)
